def fruit_distribution(s, n):
    def count_apples(s):
        parts = s.split()
        return int(parts[0]) if 'apples' in s else 0

    def count_oranges(s):
        parts = s.split()
        return int(parts[parts.index('and') + 1]) if 'oranges' in s else 0

    apples = count_apples(s)
    oranges = count_oranges(s)
    return n - apples - oranges

